// Comparable — natural order
class Employee implements Comparable<Employee> {
  public int compareTo(Employee o) { return name.compareTo(o.name); }
}

// Comparator — multiple orderings
Comparator<Employee> bySalary = Comparator.comparingDouble(Employee::getSalary);
list.sort(bySalary);

// Min-heap (default)
PriorityQueue<Integer> minQ = new PriorityQueue<>();
minQ.offer(5); minQ.offer(1); minQ.offer(3);
System.out.println(minQ.poll()); // 1

// Max-heap
PriorityQueue<Integer> maxQ = new PriorityQueue<>(Comparator.reverseOrder());
maxQ.offer(5); maxQ.offer(1);
System.out.println(maxQ.poll()); // 5

